  "WFH, field work, biometric failure…": "ঘৰৰ পৰা কাম, ক্ষেত্ৰৰ কাম, বায়’মেট্ৰিক বিফলতা…",
  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": "। কৰ্মচাৰীয়ে Face ID পঞ্জীয়ন কৰিব নোৱাৰে বা সত্যাপন কৰিবলৈ কোৱা নহয় — তেওঁলোকৰ প্ৰফাইল পৃষ্ঠাত “এই সুবিধা ব্যৱহাৰ কৰিবলৈ এডমিনৰ সৈতে যোগাযোগ কৰক” দেখুওৱা হয়, আৰু কোনো পাঞ্চৰ বাবে মুখ মিলাব লগীয়া নহয়।",
