  "9 hours": "৯ ঘণ্টা",
  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "বিকল্প পাঞ্চও অফিচৰ জিঅ’ফেঞ্চৰ ভিতৰৰ পৰা হ’ব লাগিব। ইয়াক পাঞ্চত চিহ্নিত কৰা হয় আৰু অডিট লগত নথিভুক্ত কৰা হয়।",
