  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "প্ৰতিটো বাৰ্তা (ক্লক-ইনৰ ত্ৰুটি, প্ৰফাইল পৃষ্ঠা, Face ID পঞ্জীয়নৰ স্ক্ৰীণ, নিযুক্তিৰ স্ক্ৰীণ আৰু স্বাগতম ইমেইল) এই বাছনি অনুসৰণ কৰে।",
