  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "প্ৰতিজন কৰ্মচাৰীৰ বাবে। প্ৰতিটো ৱেব পাঞ্চৰ বাবে অনুমোদিত Face IDৰ সৈতে প্ৰত্যক্ষ মুখ মিলাব লাগিব; এটা নহোৱালৈকে, তলৰ বিকল্পটো অনুমতি নিদিলে ৱেব ক্লক-ইন/আউট অৱৰুদ্ধ থাকে।",
