  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "বন্ধ (পৰামৰ্শিত): আধা দিনৰ সীমা বা তাতকৈ কম ঘণ্টাৰ সম্পূৰ্ণ হোৱা দিন আধা দিন; তাতকৈ বেছি কিন্তু পূৰ্ণ দিনৰ ন্যূনতমতকৈ কম হ’লে উপস্থিত হিচাপে থাকে আৰু কম থকা মিনিটৰ সৈতে “ঘণ্টা সম্পূৰ্ণ হোৱা নাই” বুলি দেখুওৱা হয়। চালু: পূৰ্ণ দিনৰ ন্যূনতমতকৈ কম প্ৰতিটো দিন আধা দিন।",
