  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" নিষ্ক্ৰিয় কৰা হ’ব। বৰ্তমান এই আৰ্হি ভাগ কৰি দিয়া কৰ্মচাৰীয়ে পুনৰ ভাগ কৰি নিদিয়ালৈকে ইয়াক ৰাখিব — ইতিহাস সংৰক্ষিত থাকিব।",
