  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ব্যক্তিগত নিযোগকৰ্তাৰ বাবে আবশ্যকীয় নহয়। কেৱল য’ত চৰকাৰী, PSU বা অনুদানপ্ৰাপ্ত প্ৰতিষ্ঠানে ইয়াক জনাব লাগে, বা কোনো ৰাজ্যিক উৎসাহ আঁচনিৰ বাবে লাগে, তাতহে সংগ্ৰহ কৰক। স্ব-ঘোষিত, আৰু ৰিপৰ্টিং মেনেজাৰৰ পৰা লুকুৱাই ৰখা হয়।",
