  "Start a Hire action. HR completes the hiring form here, so this employee will go directly to their dashboard after their first password change rather than receiving the self-service onboarding wizard.": "এটা নিযুক্তিৰ কাৰ্য্য আৰম্ভ কৰক। HRএ ইয়াতেই নিযুক্তিৰ ফৰ্ম সম্পূৰ্ণ কৰে, সেয়ে এই কৰ্মচাৰীয়ে স্ব-সেৱা অনবৰ্ডিং ৱিজাৰ্ড নাপাই প্ৰথমবাৰ পাছৱৰ্ড সলনি কৰাৰ পিছত পোনপটীয়াকৈ নিজৰ ডেশ্বব’ৰ্ডলৈ যাব।",
