  "Applied immediately — no pending-approval queue exists for this action yet.": "তৎক্ষণাত প্ৰয়োগ কৰা হয় — এই কাৰ্য্যৰ বাবে এতিয়ালৈকে কোনো অনুমোদন বাকী থকা শাৰী নাই।",
  "APPROVAL & REVERSIBILITY": "অনুমোদন আৰু পূৰ্বাৱস্থালৈ ঘূৰোৱা",
