  "EMPLOYEE DETAILS — NOT CHANGED BY THIS ACTION": "কৰ্মচাৰীৰ বিৱৰণ — এই কাৰ্য্যই সলনি নকৰে",
  "I have verified these values and I am authorised to apply this separation.": "মই এই মানবোৰ সত্যাপন কৰিছোঁ আৰু এই চাকৰি সমাপ্তি প্ৰয়োগ কৰিবলৈ মই অনুমোদিত।",
  "Pending approval — a real multi-stage approval chain runs on this request.": "অনুমোদন বাকী আছে — এই অনুৰোধত এটা প্ৰকৃত বহু-পৰ্যায়ৰ অনুমোদন শৃংখলা চলে।",
  "Pending approval — nothing changes until every approver on the route has approved.": "অনুমোদন বাকী আছে — পথত থকা প্ৰতিজন অনুমোদনকাৰীয়ে অনুমোদন নকৰালৈকে একো সলনি নহয়।",
  "Raised by": "উত্থাপন কৰিছে",
  "Recording a separation ends the current record and starts the exit process. It cannot be reversed — a returning employee needs a fresh Hire action.": "চাকৰি সমাপ্তি নথিভুক্ত কৰিলে বৰ্তমানৰ ৰেকৰ্ড শেষ হয় আৰু প্ৰস্থানৰ প্ৰক্ৰিয়া আৰম্ভ হয়। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি — ঘূৰি অহা কৰ্মচাৰীৰ বাবে এটা নতুন নিযুক্তিৰ কাৰ্য্য লাগিব।",
  "Reversibility": "পূৰ্বাৱস্থালৈ ঘূৰোৱাৰ সম্ভাৱনা",
  "Status on apply": "প্ৰয়োগ কৰাৰ সময়ৰ অৱস্থা",
  "This cannot be undone": "ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি",
  "unchanged": "সলনি হোৱা নাই",
  "HR Business Partner → Payroll Admin.": "HR বিজনেছ পাৰ্টনাৰ → পে’ৰ’ল এডমিন।",
  "HR, then Branch Admin (this employee is a manager, per the real separation approval chain).": "HR, তাৰ পিছত শাখা এডমিন (প্ৰকৃত চাকৰি সমাপ্তি অনুমোদন শৃংখলা অনুসৰি এই কৰ্মচাৰী এজন মেনেজাৰ)।",
  "Not reversible. Undoing a separation requires a fresh Hire action and a new employee record — the original number is not reissued.": "পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি। চাকৰি সমাপ্তি বাতিল কৰিবলৈ এটা নতুন নিযুক্তিৰ কাৰ্য্য আৰু এটা নতুন কৰ্মচাৰী ৰেকৰ্ড লাগিব — মূল নম্বৰ পুনৰ জাৰী কৰা নহয়।",
  "Reporting manager (raises) → HR Business Partner, then Payroll Admin if a new CTC is included.": "ৰিপৰ্টিং মেনেজাৰ (উত্থাপন কৰে) → HR বিজনেছ পাৰ্টনাৰ, তাৰ পিছত নতুন CTC অন্তৰ্ভুক্ত হ’লে পে’ৰ’ল এডমিন।",
  "Reporting manager (raises) → HR Business Partner.": "ৰিপৰ্টিং মেনেজাৰ (উত্থাপন কৰে) → HR বিজনেছ পাৰ্টনাৰ।",
  "Reporting manager, then HR (the real separation approval chain for this employee).": "ৰিপৰ্টিং মেনেজাৰ, তাৰ পিছত HR (এই কৰ্মচাৰীৰ বাবে প্ৰকৃত চাকৰি সমাপ্তি অনুমোদন শৃংখলা)।",
  "Requires employees.confirm — HR/Admin applies this directly, with the effective date and reason recorded in the audit trail.": "employees.confirm লাগে — HR/এডমিনে ইয়াক পোনপটীয়াকৈ প্ৰয়োগ কৰে, কাৰ্যকৰী তাৰিখ আৰু কাৰণ অডিট ট্ৰেইলত নথিভুক্ত কৰা হয়।",
  "Requires employees.edit — applied directly by whoever has that permission (typically the reporting manager or HR); no queued approval step exists for this action yet.": "employees.edit লাগে — সেই অনুমতি থকা জনে পোনপটীয়াকৈ প্ৰয়োগ কৰে (সাধাৰণতে ৰিপৰ্টিং মেনেজাৰ বা HR); এই কাৰ্য্যৰ বাবে এতিয়ালৈকে কোনো শাৰীত থকা অনুমোদনৰ পদক্ষেপ নাই।",
  "Requires employees.edit — currently held by {name} or HR; no queued approval step exists for this action yet.": "employees.edit লাগে — বৰ্তমান {name} বা HRৰ হাতত আছে; এই কাৰ্য্যৰ বাবে এতিয়ালৈকে কোনো শাৰীত থকা অনুমোদনৰ পদক্ষেপ নাই।",
  "Requires employees.edit; no queued approval step exists for this action yet.": "employees.edit লাগে; এই কাৰ্য্যৰ বাবে এতিয়ালৈকে কোনো শাৰীত থকা অনুমোদনৰ পদক্ষেপ নাই।",
  "Requires payroll.edit — typically an HR Business Partner or Payroll Admin; no queued approval step exists for this action yet.": "payroll.edit লাগে — সাধাৰণতে HR বিজনেছ পাৰ্টনাৰ বা পে’ৰ’ল এডমিন; এই কাৰ্য্যৰ বাবে এতিয়ালৈকে কোনো শাৰীত থকা অনুমোদনৰ পদক্ষেপ নাই।",
  "Reversible going forward, but any payroll run already processed on this record must be corrected through arrears.": "ভৱিষ্যতৰ বাবে পূৰ্বাৱস্থালৈ ঘূৰাব পাৰি, কিন্তু এই ৰেকৰ্ডত ইতিমধ্যে প্ৰক্ৰিয়া কৰা যিকোনো পে’ৰ’ল বকেয়াৰ যোগেদি শুধৰাব লাগিব।",
  "Reversible. A correction action delimits this record and restores the previous position; the history keeps both.": "পূৰ্বাৱস্থালৈ ঘূৰাব পাৰি। এটা সংশোধনৰ কাৰ্য্যই এই ৰেকৰ্ডৰ সীমা নিৰ্ধাৰণ কৰে আৰু আগৰ পদ পুনৰুদ্ধাৰ কৰে; ইতিহাসে দুয়োটা ৰাখে।",
  "Reversible. Record a further org assignment to move the employee back.": "পূৰ্বাৱস্থালৈ ঘূৰাব পাৰি। কৰ্মচাৰীজনক উভতাই নিবলৈ আৰু এটা সংগঠন নিযুক্তি নথিভুক্ত কৰক।",
  "This is a one-way transition from probation to confirmed/active. Verify the employee and effective date before applying.": "এইটো পৰীক্ষাকালীন সময়ৰ পৰা স্থায়ী/সক্ৰিয়লৈ এটা একমুখী পৰিৱৰ্তন। প্ৰয়োগ কৰাৰ আগতে কৰ্মচাৰী আৰু কাৰ্যকৰী তাৰিখ সত্যাপন কৰক।",
