  "Downloading face models (first time only)…": "মুখৰ মডেল ডাউনল’ড হৈ আছে (কেৱল প্ৰথমবাৰ)…",
  "Face ID registered!": "Face ID পঞ্জীয়ন কৰা হ’ল!",
  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "কৰ্মচাৰীজনক এই কেমেৰাৰ সন্মুখত বহিবলৈ কওক, তাৰ পিছত আৰম্ভ কৰক — সংৰক্ষণ কৰাৰ আগতে এটা দ্ৰুত সজীৱতা পৰীক্ষাই নিশ্চিত কৰে যে সেয়া তেৱেঁই।",
  "Please allow camera access in the browser prompt.": "অনুগ্ৰহ কৰি ব্ৰাউজাৰৰ প্ৰম্পটত কেমেৰা এক্সেছৰ অনুমতি দিয়ক।",
  "Please try again.": "অনুগ্ৰহ কৰি আকৌ চেষ্টা কৰক।",
  "Preparing face recognition": "মুখ চিনাক্তকৰণ প্ৰস্তুত কৰি আছে",
  "Register {name}'s face": "{name}ৰ মুখ পঞ্জীয়ন কৰক",
  "Register Face ID — {name}": "Face ID পঞ্জীয়ন কৰক — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID পঞ্জীয়ন কৰিবলৈ কেমেৰা এক্সেছৰ প্ৰয়োজন। আপোনাৰ ব্ৰাউজাৰৰ ছেটিংছত এই ছাইটৰ বাবে অনুমতি দিয়ক, তাৰ পিছত আকৌ চেষ্টা কৰক।",
  "Registering face ID…": "Face ID পঞ্জীয়ন হৈ আছে…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "পঞ্জীয়নৰ বাবে স্বাভাৱিক চকু টিপিয়োৱা আৰু অলপ মূৰ ঘূৰোৱা দুয়োটা প্ৰয়োজন, আৰু আমি সময়মতে দুয়োটা দেখা নাপালোঁ। তেওঁ ভালকৈ পোহৰত আৰু মাজত থকাটো নিশ্চিত কৰক, তাৰ পিছত আকৌ চেষ্টা কৰক।",
  "Requesting camera access": "কেমেৰা এক্সেছৰ অনুৰোধ কৰি আছে",
  "Saving": "সংৰক্ষণ হৈ আছে",
  "Something went wrong": "কিবা ভুল হ’ল",
  "This will replace their currently registered face ID. Position them in front of the camera and start when ready.": "ইয়াৰ দ্বাৰা তেওঁৰ বৰ্তমান পঞ্জীয়ন কৰা Face ID সলনি কৰা হ’ব। তেওঁক কেমেৰাৰ সন্মুখত থিয় কৰাওক আৰু সাজু হ’লে আৰম্ভ কৰক।",
  "Try Again": "আকৌ চেষ্টা কৰক",
