  "Update Face ID — {name}": "Face ID আপডেট কৰক — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "আমি নিৰ্ভৰযোগ্যভাৱে স্পষ্ট ছবি ল’ব নোৱাৰিলোঁ — ই তেওঁৰ স্থায়ী Face ID ৰেফাৰেন্স হ’ব, সেয়ে শুদ্ধকৈ লোৱাটো গুৰুত্বপূৰ্ণ। ভাল পোহৰ ব্যৱহাৰ কৰক আৰু তেওঁক স্থিৰ হৈ থাকিবলৈ কওক।",
