  "The draft and everything entered so far will be deleted, and its reserved employee number is released. This cannot be undone. To keep it, use Save & exit instead.": "খচৰা আৰু এতিয়ালৈকে লিখা সকলো মচি পেলোৱা হ’ব, আৰু ইয়াৰ সংৰক্ষিত কৰ্মচাৰী নম্বৰ মুকলি কৰা হ’ব। ইয়াক পূৰ্বৱৎ কৰিব নোৱাৰি। ইয়াক ৰাখিবলৈ, ইয়াৰ সলনি \"সংৰক্ষণ কৰি ওলাই যাওক\" ব্যৱহাৰ কৰক।",
