  "Type the first and last name first. Suggest builds the display name from them.": "প্ৰথমে প্ৰথম আৰু শেষ নাম লিখক। \"পৰামৰ্শ\"ই সেইবোৰৰ পৰা প্ৰদৰ্শনৰ নাম তৈয়াৰ কৰে।",
  "You will need to upload it again before hiring.": "নিযুক্তি দিয়াৰ আগতে আপুনি ইয়াক আকৌ আপলোড কৰিব লাগিব।",
