  "The new hire registers their Face ID from their Profile page, and HR approves it on": "নতুন নিযুক্তি পোৱা কৰ্মচাৰীয়ে নিজৰ প্ৰফাইল পৃষ্ঠাৰ পৰা Face ID পঞ্জীয়ন কৰে, আৰু HRএ ইয়াত অনুমোদন কৰে:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "নতুন নিযুক্তি পোৱা কৰ্মচাৰীয়ে নিজৰ প্ৰফাইল পৃষ্ঠাৰ পৰা নিজৰ Face ID পঞ্জীয়ন কৰে; ই তৎক্ষণাত সক্ৰিয় হয়।",
  "the record can still be created in Onboarding status.": "ৰেকৰ্ডটো তথাপি অনবৰ্ডিং অৱস্থাত সৃষ্টি কৰিব পাৰি।",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "ৰেকৰ্ডটো অনবৰ্ডিং অৱস্থাত সৃষ্টি কৰা হয়। ঐচ্ছিক বিৱৰণ (পিতৃ/মাতৃৰ নাম, অপ্ৰয়োজনীয় নথিপত্ৰ) পিছত সম্পূৰ্ণ কৰিব পাৰি।",
  "Until it is done they cannot clock in on the web.": "ই সম্পূৰ্ণ নোহোৱালৈকে তেওঁলোকে ৱেবত ক্লক-ইন কৰিব নোৱাৰে।",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "তাৰ আগলৈকে তেওঁলোকে অফিচৰ পৰা ক্লক-ইন কৰিব পাৰে; সেই পাঞ্চবোৰ HRৰ বাবে চিহ্নিত কৰা হয়।",
