  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "এই অনুমতিসমূহ এই পদৰ। বৰ্তমানৰ ধাৰকে এইবোৰ পায়; ভৱিষ্যতৰ ধাৰকেও একেটা এক্সেছ পাব। অনুমতি মেনেজাৰ আৰু তেওঁৰ অধীনস্থসকলৰ মাজত স্বয়ংক্ৰিয়ভাৱে নাযায়। তলত প্ৰতিটো পদক নিজৰ এক্সেছ দিয়ক।",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "দলৰ মেনেজাৰ সক্ৰিয় কৰাৰ লগে লগে তলৰ সাধাৰণ মেনেজাৰ অনুমতিবোৰো (কৰ্মচাৰী চাওক, ছুটী অনুমোদন কৰক, উপস্থিতি চাওক) চেক কৰা হ’ল যাতে এই পদত ০টা অনুমতি নাথাকে। সংৰক্ষণ কৰাৰ আগতে নিবিচৰাবোৰ আনচেক কৰক।",
