  "Waiting for HR to sign off from": "HRএ চাইন অফ কৰালৈ অপেক্ষা কৰি আছে, ইয়াৰ পৰা",
  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "HR/এডমিনে পোনপটীয়াকৈ L1 পদক্ষেপ সম্পূৰ্ণ কৰালৈ অপেক্ষা কৰি আছে — এই চক্ৰৰ বাবে কোনো মেনেজাৰ কনফিগাৰ কৰা হোৱা নাই।",
  "Waiting for other managers to approve. Refresh to check latest status.": "আন মেনেজাৰসকলে অনুমোদন কৰালৈ অপেক্ষা কৰি আছে। শেহতীয়া অৱস্থা চাবলৈ ৰিফ্ৰেচ কৰক।",
