  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "কৰ্মচাৰীসকলে নিজৰ দৰমহাৰ ছিপ স্বীকাৰ কৰিছে। বেংকৰ তথ্য লক কৰিবলৈ আৰু NEFT CSV প্ৰস্তুত কৰিবলৈ দৰমহা স্থানান্তৰ নিশ্চিত কৰক।",
