  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} জন কৰ্মচাৰীৰ বাবে দৰমহা স্থানান্তৰ লক কৰা হৈছে। পে’ৰ’ল পৰিশোধ কৰা বুলি চিহ্নিত কৰাৰ আগতে NEFT CSV ডাউনল’ড কৰি আপোনাৰ বেংকত দাখিল কৰক।",
  "Salary transfer readiness is unavailable.": "দৰমহা স্থানান্তৰৰ প্ৰস্তুতি উপলব্ধ নহয়।",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "ই সকলো {count} জন কৰ্মচাৰীৰ বৰ্তমানৰ বেংকৰ তথ্য আৰু নিট দৰমহা এটা স্থানান্তৰ বেচত লক কৰে। নিশ্চিত কৰাৰ পিছত NEFT CSV ডাউনল’ড কৰক আৰু পে’ৰ’ল পৰিশোধ কৰা বুলি চিহ্নিত কৰাৰ আগতে আপোনাৰ বেংকৰ জৰিয়তে দাখিল কৰক।",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ই সকলো {count}খন দৰমহাৰ ছিপ (মুঠ {amount}) পৰিশোধ কৰা বুলি চিহ্নিত কৰে আৰু এই পে’ৰ’ল ৰান বন্ধ কৰে। ই নিজে ধন স্থানান্তৰ নকৰে — স্থানান্তৰ ইতিমধ্যে হৈ গৈছে বুলি নথিভুক্ত কৰে। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ই সকলো {count}খন দৰমহাৰ ছিপ (মুঠ {amount}) পৰিশোধ কৰা বুলি চিহ্নিত কৰে আৰু এই পে’ৰ’ল ৰান বন্ধ কৰে। ই নিজে ধন স্থানান্তৰ নকৰে — স্থানান্তৰ ইতিমধ্যে হৈ গৈছে বুলি নথিভুক্ত কৰে। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
