  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ই এই চক্ৰৰ সকলো {count} জন কৰ্মচাৰীৰ দৰমহা গোড়াৰ পৰা পুনৰ গণনা কৰে, বৰ্তমানৰ সংখ্যাবোৰ ওভাৰৰাইট কৰে — এই দৰমহাৰ ছিপবোৰত ইতিমধ্যে কৰা যিকোনো হাতে কৰা বোনাছ বা প্ৰতিপূৰণৰ সমন্বয়ো ইয়াৰ অন্তৰ্ভুক্ত। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ই এই চক্ৰৰ সকলো {count} জন কৰ্মচাৰীৰ দৰমহা গোড়াৰ পৰা পুনৰ গণনা কৰে, বৰ্তমানৰ সংখ্যাবোৰ ওভাৰৰাইট কৰে — এই দৰমহাৰ ছিপবোৰত ইতিমধ্যে কৰা যিকোনো হাতে কৰা বোনাছ বা প্ৰতিপূৰণৰ সমন্বয়ো ইয়াৰ অন্তৰ্ভুক্ত। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
