  "Leave Encashment": "ছুটী নগদীকৰণ",
  "Net Recoverable from Employee": "কৰ্মচাৰীৰ পৰা আদায়যোগ্য নিট",
  "Notice Period Recovery": "নোটিচ সময়কালৰ আদায়",
  "Notice period shortfall:": "নোটিচ সময়কালৰ ঘাটি:",
