  "Other Adjustment: {amount}": "অন্য সমন্বয়: {amount}",
  "Pro-rata Salary": "অনুপাতিক দৰমহা",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "অনুপাতিক দৰমহা, ছুটী নগদীকৰণ আৰু নোটিচ সময়কালৰ ঘাটি স্বয়ংক্ৰিয়ভাৱে গণনা কৰা হয় (CTC ÷ 30, অৰ্জিত ছুটীৰ বাকী) — ই পৰ্যালোচনাৰ বাবে আৰম্ভণিৰ অনুমান, চূড়ান্ত সংখ্যা নহয়। গ্ৰেচুইটি, বোনাছ, প্ৰতিপূৰণ, অগ্ৰিম আৰু TDS সদায় হাতে দিয়া হয়।",
  "Settlement finalized.": "নিষ্পত্তি চূড়ান্ত কৰা হ’ল।",
  "Settlement updated.": "নিষ্পত্তি আপডেট কৰা হ’ল।",
  "This is a recovery — the employee owes the company (net payable may be negative)": "এয়া এটা আদায় — কৰ্মচাৰীয়ে কোম্পানীক দিব লাগে (নিট প্ৰদেয় ঋণাত্মক হ’ব পাৰে)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ই সম্পূৰ্ণ আৰু চূড়ান্ত নিষ্পত্তি {amount}ৰ নিট প্ৰদেয়ত লক কৰে। চূড়ান্ত কৰাৰ পিছত, এই নিষ্পত্তিৰ কোনো ক্ষেত্ৰ — গ্ৰেচুইটি, বোনাছ, প্ৰতিপূৰণ, অগ্ৰিম, TDS বা সমন্বয় — আৰু সম্পাদনা কৰিব নোৱাৰি। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ই সম্পূৰ্ণ আৰু চূড়ান্ত নিষ্পত্তি কৰ্মচাৰীৰ পৰা আদায়যোগ্য {amount}ৰ নিটত লক কৰে। চূড়ান্ত কৰাৰ পিছত, এই নিষ্পত্তিৰ কোনো ক্ষেত্ৰ — গ্ৰেচুইটি, বোনাছ, প্ৰতিপূৰণ, অগ্ৰিম, TDS বা সমন্বয় — আৰু সম্পাদনা কৰিব নোৱাৰি। ইয়াক পূৰ্বাৱস্থালৈ ঘূৰাব নোৱাৰি।",
