  "Date Format": "তাৰিখৰ বিন্যাস",
  "Default Currency": "ডিফল্ট মুদ্ৰা",
  "Defaults follow the jurisdiction and country above. Override any of them if your reporting needs differ.": "ডিফল্টবোৰ ওপৰৰ এখতিয়াৰ আৰু দেশ অনুসৰি হয়। আপোনাৰ প্ৰতিবেদনৰ প্ৰয়োজন বেলেগ হ’লে যিকোনো অভাৰৰাইড কৰক।",
  "How amounts, dates, and times display across the app and on documents.": "এপ আৰু নথিপত্ৰত ধনৰাশি, তাৰিখ আৰু সময় কেনেকৈ দেখুওৱা হয়।",
