  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "প্ৰতিটো আইডি ৮ আংকৰ আৰু সম্পূৰ্ণ সংখ্যাৰে গঠিত। প্ৰতিটো কৰ্মীৰ প্ৰকাৰৰ নিজা পৰিসৰ আছে, সেয়ে প্ৰথম আংকে প্ৰকাৰ বুজায়। নিযুক্তিৰ সময়ত আইডি স্বয়ংক্ৰিয়ভাৱে বাছনি কৰা হয়; পিছত কাৰোবাৰ প্ৰকাৰ সলনি কৰিলেও তেওঁৰ বৰ্তমানৰ আইডি সলনি নহয়।",
