  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "মনোনীত ব্যক্তি পৰিয়ালৰ তালিকাৰ পৰা বাছনি কৰা হয়, আৰু ইয়াত এতিয়ালৈকে কোনো নাই। ওপৰত নাম সহ এজন পৰিয়ালৰ সদস্য যোগ কৰক, তাৰ পিছত মনোনীত ব্যক্তি যোগ কৰক।",
