  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "কৰ্মচাৰীৰ ওপৰত নিৰ্ভৰশীল বা তলত মনোনীত হ’ব পৰা লোকসকলক যোগ কৰক। এজন ব্যক্তিক এবাৰ যোগ কৰা হয় আৰু তেওঁক মনোনীত ব্যক্তি হিচাপে বাছনি কৰিব পাৰি।",
