  "You cannot approve your own leave or expense requests.": "আপুনি আপোনাৰ নিজৰ ছুটী বা খৰচৰ অনুৰোধ অনুমোদন কৰিব নোৱাৰে।",
  "You stay signed in for up to 7 days. The short-lived part of your sign-in lasts 15 minutes and is renewed automatically while you are signed in.": "আপুনি ৭ দিনলৈকে ছাইন ইন হৈ থাকে। আপোনাৰ ছাইন ইনৰ চুটি-জীৱী অংশ ১৫ মিনিট চলে আৰু আপুনি ছাইন ইন হৈ থাকোঁতে স্বয়ংক্ৰিয়ভাৱে নৱীকৰণ হয়।",
