  "Location access is required for work-from-home punch in/out. Please allow location in your browser settings.": "ঘৰৰ পৰা কামৰ পাঞ্চ ইন/আউটৰ বাবে অৱস্থান এক্সেছ প্ৰয়োজন। অনুগ্ৰহ কৰি আপোনাৰ ব্ৰাউজাৰৰ ছেটিংছত অৱস্থানৰ অনুমতি দিয়ক।",
  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "অনুগ্ৰহ কৰি প্ৰথমে আপোনাৰ Face ID পঞ্জীয়ন কৰক (প্ৰফাইল > মোৰ মুখ পঞ্জীয়ন কৰক), তাৰ পিছত পাঞ্চ ইন কৰিবলৈ উভতি আহক।",
