  "Unable to determine your location. Please check your device's location settings and try again.": "আপোনাৰ অৱস্থান নিৰ্ণয় কৰিব পৰা নগ’ল। অনুগ্ৰহ কৰি আপোনাৰ ডিভাইচৰ অৱস্থানৰ ছেটিংছ পৰীক্ষা কৰি আকৌ চেষ্টা কৰক।",
