  "Leave recorded — {days} day from {date}.": "ছুটী নথিভুক্ত হ’ল — {date}ৰ পৰা {days} দিন।",
  "Leave recorded — {days} days from {date}.": "ছুটী নথিভুক্ত হ’ল — {date}ৰ পৰা {days} দিন।",
  "That range contains only weekly offs.": "সেই পৰিসৰত কেৱল সাপ্তাহিক বন্ধ আছে।",
  "Could not download this report.": "এই প্ৰতিবেদন ডাউনল’ড কৰিব পৰা নগ’ল।",
