  "That did not go through. Please try again.": "সেয়া সম্পূৰ্ণ নহ’ল। অনুগ্ৰহ কৰি আকৌ চেষ্টা কৰক।",
  "Timesheet approved.": "টাইমশ্বীট অনুমোদিত হ’ল।",
  "Timesheet reopened for correction.": "সংশোধনৰ বাবে টাইমশ্বীট পুনৰ খোলা হ’ল।",
  "Timesheet sent back to the employee.": "টাইমশ্বীট কৰ্মচাৰীলৈ ঘূৰাই পঠোৱা হ’ল।",
  "Could not save the timesheet.": "টাইমশ্বীট সংৰক্ষণ কৰিব পৰা নগ’ল।",
